import type { MetadataRoute } from "next";

import { getCatalogSnapshot } from "@/lib/catalog";
import { site } from "@/lib/site";

export default function sitemap(): MetadataRoute.Sitemap {
  const snapshot = getCatalogSnapshot();
  const lastModified = new Date(snapshot.generated_at);
  const publicRoutes = [
    "",
    "/catalog",
    "/show-programs",
    "/prices",
    "/o-nas",
    "/contacts",
    "/party-builder",
  ];
  return [
    ...publicRoutes.map((route) => ({
      url: `${site.canonicalUrl}${route}`,
      lastModified,
      changeFrequency: route === "" ? ("weekly" as const) : ("monthly" as const),
      priority: route === "" ? 1 : route === "/catalog" || route === "/show-programs" ? 0.9 : 0.7,
    })),
    ...snapshot.characters.map((character) => ({
      url: `${site.canonicalUrl}/character/${character.slug}`,
      lastModified: new Date(character.updated_at || snapshot.generated_at),
      changeFrequency: "monthly" as const,
      priority: 0.8,
    })),
    ...snapshot.shows.map((show) => ({
      url: `${site.canonicalUrl}/show-programs/${show.slug}`,
      lastModified: new Date(show.updated_at || snapshot.generated_at),
      changeFrequency: "monthly" as const,
      priority: 0.85,
    })),
  ];
}
